from threetears.evals import Eval

from curve import curve_file

def grade(case):
    """The student's letter, from their section's curve."""
    results = curve_file(f"data/marks/section-{case['section']}.csv")
    return {"letter": next((r.letter for r in results if r.student == case["student"]), None)}


def registrar_letter(case, out):
    """The student gets the letter the registrar holds."""
    return out["letter"] == case["letter"]

students = Eval("data/registrar.jsonl", runner=grade, grader=[registrar_letter], k=1)
